import tkinter as tk
import tkinter.ttk as ttk
from tkinter import *
from tkinter import filedialog
from tkinter import messagebox
import os


def robocopy(event):
    okcancel= messagebox.askokcancel("Copy?","Do you want to copy "+leftpath+" to "+rightpath+"?",default="ok")
    if okcancel== True:
        #os.system("cmd dir")
        command="start cmd /k robocopy "+'"'+leftpath+'"'+" "+'"'+rightpath+'"'+" /S /R:0 /W:0"
        #print (command)
        os.system(command)


def browsewin():
    global leftdir_label
    global rightdir_label
    global top
    img=b''

    root= tk.Tk()
    top= root
    top.title("RoboGUI")
    favicon=tk.PhotoImage(data=img) 
    root.wm_iconphoto(True, favicon)
    top.geometry("500x155")
    top.resizable(0,0)
    
    leftdir_label=Label(top,wraplength=400,justify="left")
    leftdir_label.place(x=15,y=15,height=40,width=400)

    rightdir_label=Label(top,wraplength=400,justify="left")
    rightdir_label.place(x=15,y=65,height=40,width=400)

    left_button= Button(top)
    left_button.configure(text="Source")
    left_button.place(x=400,y=15,height=30,width=70)
    left_button.bind("<Button-1>", leftselect)

    right_button= Button(top)
    right_button.configure(text="Destination")
    right_button.place(x=400,y=65,height=30,width=70)
    right_button.bind("<Button-1>", rightselect)
    
    robo_button= Button(top)
    robo_button.configure(text="Robocopy")
    robo_button.place(x=185,y=115,height=30,width=70)
    robo_button.bind("<Button-1>", robocopy)

    quit_button= Button(top)
    quit_button.configure(text="Exit")
    quit_button.place(x=270,y=115,height=30,width=60)
    quit_button.bind("<Button-1>", quit_program)
    
    filedialogs()
    root.mainloop()

def leftselect(event):
    global leftpath
    leftpath=filedialog.askdirectory(title="Source")
    leftdir_label.configure(text=leftpath)

def rightselect(event):
    global rightpath
    rightpath=filedialog.askdirectory(title="Destination")
    rightdir_label.configure(text=rightpath)

def filedialogs():
    global leftpath
    global rightpath
    leftpath=filedialog.askdirectory(title="Source")
    leftdir_label.configure(text=leftpath)
    rightpath=filedialog.askdirectory(title="Destination")
    rightdir_label.configure(text=rightpath)

def quit_program(event):
    okcancel= messagebox.askokcancel("Exit?","Do you want to exit the program?",default="ok")
    if okcancel== True:
        top.destroy()

def main():
    browsewin()

main()
#root.mainloop()

